import * as React from "react";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import TableHead from "@mui/material/TableHead";
import TableRow from "@mui/material/TableRow";
import Paper from "@mui/material/Paper";
import DeleteIcon from "@mui/icons-material/Delete";
import swal from "sweetalert";

const isObject = (value) => {
  return typeof value === "object" && value !== null;
};

export default function BasicTable({ data, questionType }) {
  const convertData = (customer) => {
    const result = [];
    for (let key in customer) {
      if (customer.hasOwnProperty(key)) {
        result.push({ q: key, a: customer[key] });
      }
    }
    return result;
  };
  const handleDeleteClick = (id) => {
    swal({
      title: "آیا از حذف مطمئنید؟",
      text: "پس از حذف، نمی توانید این اطلاعات را بازیابی کنید!",
      icon: "warning",
      buttons: true,
      dangerMode: true,
    }).then((willDelete) => {
      if (willDelete) {
        // Perform the delete action here using the provided URL and the id
        fetch(`https://ffqbackend.liara.run/${questionType}/${id}`, {
          method: "DELETE",
        })
          .then((response) => {
            if (response.ok) {
              // Optionally, you can update the UI to indicate the row has been deleted
              console.log("Data deleted successfully");
            } else {
              console.error("Failed to delete data");
            }
          })
          .catch((error) => {
            console.error("Error deleting data:", error);
          });
      }
    });
  };

  return (
    <>
      {data.length ? (
        <TableContainer
          component={Paper}
          style={{
            width: "95%",
            margin: "auto",
          }}
        >
          <Table sx={{ minWidth: 650 }} aria-label="simple table">
            <TableHead>
              <TableRow>
                {convertData(data[0]).map((item, i) => (
                  <TableCell
                    style={{
                      whiteSpace: "nowrap",
                      textAlign: "center",
                    }}
                    key={`cell-${i}`}
                  >
                    {item.q}
                  </TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {data.map((customer, index) => (
                <TableRow
                  key={index}
                  sx={{ "&:last-child td, &:last-child th": { border: 0 } }}
                >
                  {convertData(customer).map((item, i) => (
                    <TableCell
                      key={i}
                      style={{ whiteSpace: "nowrap", textAlign: "center" }}
                    >
                      {isObject(item.a)
                        ? Object.values(item.a).join(" ")
                        : item.a}
                    </TableCell>
                  ))}
                  <TableCell>
                    <DeleteIcon
                      className="text-red-500 items-center justify-center cursor-pointer"
                      onClick={() => handleDeleteClick(customer.id)}
                    />
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      ) : (
        <></>
      )}
    </>
  );
}
