import React, { useEffect, useState, useRef } from "react";
import { useFormik } from "formik";
import * as Yup from "yup";
import axios from "axios";
import Modal from "./../organism/Modal";
import swal from "sweetalert";
import { useNavigate } from "react-router";
import jalaliMoment from "jalali-moment";

import "./../App.css";
import ScrollProgressCircle from "./../Components/ScrollProgressCircle";
const DynamicFormNewFFQ = ({ questions, questionType, passwordRequired }) => {
  const [passwordModalOpen, setPasswordModalOpen] = useState(false);
  const [password, setPassword] = useState("");
  const [formDisplay, setFormDisplay] = useState(
    localStorage.getItem(`${questionType}admin`) === "true" ? true : false
  );
  const navigate = useNavigate();
  const [shouldScrollToError, setShouldScrollToError] = useState(false);
  const firstErrorFieldRef = useRef(null);
  const [selectedOptions, setSelectedOptions] = useState({});
  const [ip, setIP] = useState("");
  const [startTime, setStartTime] = useState(Date.now()); // زمان شروع

  const validationSchema = Yup.object().shape(
    questions.reduce((schema, question) => {
      schema[question.id] = question.validation;

      if (question.id === "تلفن همراه جایگزین") {
        schema[question.id] = schema[question.id].test({
          name: "notEqual",
          message:
            "شماره تلفن همراه جایگزین نمی تواند با تلفن همراه (موبایل) یکسان باشد؛ لطفا شماره دیگری وارد کنید.",
          test: function (value) {
            // Access the values of other fields using `this.parent`
            const mobileNumber = this.parent["تلفن همراه (موبایل) :"];
            return value != mobileNumber;
          },
        });
      }

      return schema;
    }, {})
  );

  const handleImageClick = (imageUrl) => {
    const isLargeScreen = window.innerWidth >= 1024; // بررسی اندازه صفحه نمایش
    const modalStyles = isLargeScreen
      ? { width: "95%", maxWidth: "800px" }
      : { width: "95%" };

    swal({
      content: {
        element: "div",
        attributes: {
          innerHTML: `<img src="${imageUrl}" style="max-width: 100%; height: auto;" />`,
        },
      },
      buttons: "بستن تصویر",
    });

    setTimeout(() => {
      const modalElement = document.querySelector(".swal-modal");
      if (modalElement) {
        Object.assign(modalElement.style, modalStyles);
      }
    }, 0);
  };

  const formik = useFormik({
    initialValues: questions.reduce((values, question) => {
      values[question.id] = "";
      return values;
    }, {}),
    validationSchema,
    onSubmit: async (values) => {
      // محاسبه زمان حضور
      const currentTime = Date.now();
      const timeSpent = currentTime - startTime; // زمان حضور به میلی ثانیه
      values.timeSpent = formatTime(timeSpent); // افزودن زمان فرمت شده به داده‌ها

      // Use async/await to handle the fetch promise
      const currentDate = jalaliMoment().format("jYYYY/jMM/jDD HH:mm:ss");
      values.submissionDateTime = currentDate;
      values.ip = ip;

      try {
        const response = await fetch(
          `https://ffqbackend.liara.run/${questionType}`,
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify(values),
          }
        );

        if (response.status === 201) {
          localStorage.setItem(questionType, true);
          swal({
            title: "اطلاعات با موفقیت ثبت شد.",
            icon: "success",
            buttons: "متوجه شدم",
          });
          setTimeout(() => {
            navigate("/thanks"); // Use navigate to go to the home page after a delay
          }, 1000);
        }
      } catch (error) {
        // Handle any fetch errors or rejections
        swal({
          title:
            "در ثبت اطلاعات مشکلی وجود دارد لطفا با شماره 09981110126 تماس بگیرید؛ با تشکر از شما",
          icon: "error",
          buttons: "متوجه شدم",
        });
        console.log("Error:", error);
      }
    },
  });
  const handleCheckboxChange = (questionId, optionId) => {
    setSelectedOptions((prevSelectedOptions) => {
      const selectedOptionsForQuestion = prevSelectedOptions[questionId] || [];

      const updatedOptions =
        optionId === "هیچکدام"
          ? selectedOptionsForQuestion.includes("هیچکدام")
            ? []
            : [optionId]
          : selectedOptionsForQuestion.includes("هیچکدام")
          ? [optionId]
          : selectedOptionsForQuestion.includes(optionId)
          ? selectedOptionsForQuestion.filter(
              (selectedOption) => selectedOption !== optionId
            )
          : [...selectedOptionsForQuestion, optionId];

      // Update Formik state
      formik.handleChange({
        target: {
          name: questionId,
          value: updatedOptions,
        },
      });

      return {
        ...prevSelectedOptions,
        [questionId]: updatedOptions,
      };
    });
  };
  const shouldShowOtherInput = (questionId) => {
    const question = questions.find((q) => q.id === questionId);
    return question?.type === "radio" && formik.values[questionId] === "other";
  };
  const handlePasswordSubmit = (e) => {
    e.preventDefault();
    if (
      (questionType === "newcaseffq" && password === "10010") ||
      (questionType === "newcontrolffq" && password === "10010") ||
      (questionType === "newabadancaseffq" && password === "10012") ||
      (questionType === "newabadancontrolffq" && password === "10013") ||
      (questionType === "diabeticfootulcerffq" && password === "10089") ||
      (questionType === "ffqvalidation" && password === "10066") ||
      (questionType === "diabeticfootulcerdemographic" && password === "10089")
    ) {
      setPasswordModalOpen(false);
      setFormDisplay(true);
    } else if (
      (questionType === "diabeticfootulcerffq" ||
        questionType === "diabeticfootulcerdemographic") &&
      password === "889975"
    ) {
      setPasswordModalOpen(false);
      setFormDisplay(true);
      localStorage.setItem(`${questionType}admin`, true);
    } else if (
      (questionType === "newcaseffq" || questionType === "newcontrolffq") &&
      password === "10510"
    ) {
      setPasswordModalOpen(false);
      setFormDisplay(true);
      localStorage.setItem(`${questionType}admin`, true);
    } else if (questionType === "ffqvalidation" && password === "10068") {
      setPasswordModalOpen(false);
      setFormDisplay(true);
      localStorage.setItem(`${questionType}admin`, true);
    } else {
      swal({
        title: "رمز عبور نادرست می باشد!",
        icon: "error",
        buttons: "OK",
      });
    }
  };
  useEffect(() => {
    if (formDisplay) {
      setStartTime(Date.now()); // ثبت زمان شروع
    }
  }, [formDisplay]);
  useEffect(() => {
    const fetchIP = async () => {
      try {
        const response = await axios.get("https://api.ipify.org?format=json");
        setIP(response.data.ip);
      } catch (error) {
        console.error("Error fetching the public IP address:", error);
      }
    };

    fetchIP();
  }, []);

  useEffect(() => {
    if (passwordRequired) {
      setPasswordModalOpen(true);
    } else {
      setPasswordModalOpen(false);
      setFormDisplay(true);
    }
  }, []);

  useEffect(() => {
    if (shouldScrollToError && firstErrorFieldRef.current) {
      firstErrorFieldRef.current.scrollIntoView({ behavior: "smooth" });
      setShouldScrollToError(false); // Set shouldScrollToError to false after initial scroll
    }
  }, [formik.errors, formik.values, firstErrorFieldRef, shouldScrollToError]);

  const formatTime = (milliseconds) => {
    const totalSeconds = Math.floor(milliseconds / 1000);
    const hours = Math.floor(totalSeconds / 3600);
    const minutes = Math.floor((totalSeconds % 3600) / 60);
    const seconds = totalSeconds % 60;

    return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(
      2,
      "0"
    )}:${String(seconds).padStart(2, "0")}`;
  };

  if (!formDisplay) {
    return (
      <div>
        <Modal
          isOpen={passwordModalOpen}
          onClose={() => setPasswordModalOpen(false)}
        >
          <form onSubmit={handlePasswordSubmit}>
            <input
              type="password"
              className="w-full border-2 p-2 rounded-lg"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            <button
              type="submit"
              className="bg-blue-500 w-full p-2 my-2 text-white rounded-lg"
            >
              ثبت رمز
            </button>
          </form>
        </Modal>
      </div>
    );
  }

  return (
    <form onSubmit={formik.handleSubmit} className="flex flex-col flex-wrap">
      {questions.map((question, index) => (
        <div
          key={question.id}
          className={`w-[100%] lg:mx-2 max-lg:px-2 my-4 ${
            question.img && question.img.length > 0
              ? "lg:flex max-lg:block max-lg:items-start "
              : ""
          }`}
        >
          {question.img && question.img.length > 0 && (
            <div className="relative">
              <img
                src={question.img}
                loading="lazy"
                className="lg:!w-96 lg:!h-96 max-lg:w-full rounded-lg cursor-pointer border-blue-500 border-4 ml-2"
                alt={`تصویر ${question.label}`}
                onClick={() => handleImageClick(question.img)}
              />
              {question.type === "radio" && (
                <div className="absolute w-full lg:bottom-3 max-lg:bottom-2 left-0 text-center">
                  <p className="bg-black bg-opacity-30 opacity-100 text-xl text-white p-2">
                    {question.label}
                    <p>{question.subLabel}</p>
                  </p>
                </div>
              )}
            </div>
          )}
          <div>
            <div
              className={`flex max-lg:p-2 max-lg:rounded-lg ${
                question.label &&
                question.label.length > 35 &&
                question.type === "text"
                  ? "flex-col !items-start !justify-start text-right"
                  : ""
              } ${
                question.type === "text"
                  ? "justify-start max-lg:justify-center my-1 lg:mx-1 items-center"
                  : ""
              } ${
                question.label &&
                question.label.length > 35 &&
                question.type === "number"
                  ? "flex-col !items-start !justify-start text-right"
                  : ""
              } ${
                question.type === "number"
                  ? "justify-start max-lg:justify-center my-1 lg:mx-1 items-center"
                  : ""
              } lg:mx-1 w-full 
              
              ${
                question.label && question.serving && question.type === "radio"
                  ? "lg:w-[97%] lg:rounded-lg bg-blue-500 max-lg:my-2"
                  : ""
              }`}
            >
              <p
                className={`lg:mx-1
              ${
                question.label &&
                question.label.length > 35 &&
                question.type === "text"
                  ? "!w-[100] mt-4"
                  : ""
              } ${
                  question.type === "text" && question.label.length < 35
                    ? "!w-[10%] text-right max-lg:text-right max-lg:w-[30%]"
                    : ""
                } ${
                  question.label &&
                  question.label.length > 35 &&
                  question.type === "number"
                    ? "!w-[100] mt-4"
                    : ""
                } ${
                  question.type === "number" && question.label.length < 35
                    ? "!w-[10%] text-right max-lg:text-right max-lg:w-[30%]"
                    : ""
                }
                ${
                  question.type === "radio"
                    ? "w-full text-center font-extrabold text-white lg:p-3 lg:text-lg"
                    : ""
                }`}
              >
                {question.type !== "radio" ? question.label : ""}
                {question.type === "radio" && question.serving
                  ? "بار مصرف : " + question.serving
                  : ""}
              </p>
              {question.type === "text" && (
                <div
                  className={`lg:w-[50%]  ${
                    question.label &&
                    question.label.length > 35 &&
                    question.type === "text"
                      ? "max-lg:w-[100%] mt-2"
                      : "max-lg:w-[60%]"
                  } ${
                    question.label &&
                    question.label.length > 35 &&
                    question.type === "number"
                      ? "max-lg:w-[100%] mt-2"
                      : "max-lg:w-[60%]"
                  }`}
                >
                  <input
                    type="text"
                    name={question.id}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    value={formik.values[question.id] || ""}
                    ref={
                      Object.keys(formik.errors)[0] === question.id
                        ? firstErrorFieldRef
                        : null
                    }
                    placeholder={question.placeholder}
                    className={`w-full rounded-md p-2 max-sm:placeholder:!text-[13px] max-sm:placeholder:!font-extrabold border-gray-300 border-[1px] ${
                      question.label &&
                      question.label.length > 35 &&
                      question.type === "text"
                        ? ""
                        : ""
                    }`}
                  />
                  {formik.touched[question.id] &&
                    formik.errors[question.id] && (
                      <div className="text-red-500 mt-1">
                        {formik.errors[question.id]}
                      </div>
                    )}
                </div>
              )}
              {question.type === "number" && (
                <div
                  className={`${
                    question.label &&
                    question.label.length > 35 &&
                    question.type === "number"
                      ? "max-lg:w-[100%] mt-2"
                      : "max-lg:w-[60%]"
                  }`}
                >
                  <input
                    type="number"
                    name={question.id}
                    onChange={formik.handleChange}
                    onBlur={formik.handleBlur}
                    value={formik.values[question.id] || ""}
                    ref={
                      Object.keys(formik.errors)[0] === question.id
                        ? firstErrorFieldRef
                        : null
                    }
                    placeholder={question.placeholder}
                    className={`w-full rounded-md p-2 max-sm:placeholder:!text-[13px] max-sm:placeholder:!font-extrabold border-gray-300 border-[1px] ${
                      question.label &&
                      question.label.length > 35 &&
                      question.type === "number"
                        ? ""
                        : ""
                    }`}
                  />
                  {formik.touched[question.id] &&
                    formik.errors[question.id] && (
                      <div className="text-red-500 mt-1">
                        {formik.errors[question.id]}
                      </div>
                    )}
                </div>
              )}
            </div>
            {question.type === "radio" && (
              <div
                role="group"
                className={`flex flex-col lg:flex-row lg:flex-wrap mt-2`}
              >
                {question.options.map((option, idx) => (
                  <label
                    key={option.id}
                    className={`flex items-center !cursor-pointer border-2 p-2 my-1 rounded-lg ${
                      formik.values[question.id] === option.id
                        ? "border-blue-500 border-4"
                        : ""
                    } ${
                      idx % 2 === 0 ? "lg:mr-2" : ""
                    } lg:w-[48%] lg:mr-2 max-lg:w-full`}
                  >
                    <input
                      type="radio"
                      name={question.id}
                      value={option.id}
                      onChange={formik.handleChange}
                      onBlur={formik.handleBlur}
                      ref={
                        Object.keys(formik.errors)[0] === question.id
                          ? firstErrorFieldRef
                          : null
                      }
                      checked={formik.values[question.id] === option.id}
                      className="mr-2 w-4 h-4 cursor-pointer checked:border-blue-500 checked:border-2"
                    />
                    <span className="text-sm mr-2">{option.label}</span>
                  </label>
                ))}
                {shouldShowOtherInput(question.id) && (
                  <>
                    <input
                      type="text"
                      name={`${question.id}-other`}
                      onChange={formik.handleChange}
                      onBlur={formik.handleBlur}
                      value={formik.values[`${question.id}-other`] || ""}
                      ref={
                        Object.keys(formik.errors)[0] === question.id
                          ? firstErrorFieldRef
                          : null
                      }
                      placeholder="Please specify..."
                      className="input-style"
                    />
                    {formik.touched[`${question.id}-other`] &&
                      formik.errors[`${question.id}-other`] && (
                        <div className="text-red-500 mt-1">
                          {formik.errors[`${question.id}-other`]}
                        </div>
                      )}
                  </>
                )}
                {formik.touched[question.id] && formik.errors[question.id] && (
                  <div className="text-red-500 mr-10 mt-1">
                    {formik.errors[question.id]}
                  </div>
                )}
              </div>
            )}
            <div className="w-full flex items-center justify-center">
              {question.type === "description" && (
                <div className="border-2 text-white w-[95%] bg-blue-500 p-4 text-center rounded-xl">
                  {question.description}
                </div>
              )}
            </div>
            {question.type === "checkbox" && (
              <div
                role="group"
                className="flex items-center justify-center flex-wrap flex-row"
              >
                {question.options.map((option) => (
                  <label
                    key={option.id}
                    className={`mx-1 cursor-pointer my-1 border-2 p-2 rounded-lg ${
                      option.label.length > 23 || option.label === "سایر"
                        ? "w-[92%]"
                        : "w-[45%]"
                    } ${
                      option.label === "هیچکدام" ? "text-red-500 !w-[92%]" : ""
                    } ${
                      selectedOptions[question.id]?.includes(option.id)
                        ? "border-blue-500 border-2 bg-blue-500 text-white"
                        : ""
                    } flex flex-col items-center`}
                  >
                    <input
                      type="checkbox"
                      name={question.id}
                      value={option.id}
                      onChange={() =>
                        handleCheckboxChange(question.id, option.id)
                      }
                      onBlur={formik.handleBlur}
                      checked={selectedOptions[question.id]?.includes(
                        option.id
                      )}
                      className="mr-0 w-4 h-0 cursor-pointer checked:border-blue-500  checked:border-2"
                    />
                    <span className="text-sm mr-2">{option.label}</span>
                  </label>
                ))}
                {formik.touched[question.id] && formik.errors[question.id] && (
                  <div className="text-red-500 mt-1">
                    {formik.errors[question.id]}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      ))}
      <ScrollProgressCircle />
      <button
        type="submit" // Change the type to "button" to prevent automatic form submission
        onClick={() => {
          if (Object.keys(formik.errors).length > 0) {
            setShouldScrollToError(true);
            // Extract question labels with validation errors, excluding specific labels
            const excludedLabels = ["Label1", "Label2"]; // Specify the labels to be excluded
            const errorLabels = Object.keys(formik.errors)
              .map((errorKey) => {
                const question = questions.find(
                  (question) => question.id === errorKey
                );
                return question && !excludedLabels.includes(question.label)
                  ? question.label
                  : "";
              })
              .filter((label) => label !== "");

            // Construct the custom error message
            const errorMessageHTML = errorLabels
              .map(
                (message) =>
                  `<div style="font-size: 20px; color: black;">${message}</div>`
              )
              .join("");

            // Display the custom error message in Swal with red title
            swal({
              title: "خطا در ثبت اطلاعات، لطفا موارد زیر به درستی وارد نمایید:",
              content: {
                element: "div",
                attributes: {
                  innerHTML: errorMessageHTML,
                },
              },
              icon: "error",
              buttons: "متوجه شدم",
            }).then(() => {
              const firstErrorField = Object.keys(formik.errors)[0];
              if (
                firstErrorField &&
                formik.errors[firstErrorField] &&
                formik.touched[firstErrorField]
              ) {
                const errorField = document.getElementsByName(firstErrorField);
                if (errorField.length > 0) {
                  errorField[0].scrollIntoView({
                    behavior: "smooth",
                    block: "center",
                  });
                }
              }
            });
          } else {
            formik.handleSubmit(); // Manually trigger form submission if there are no errors
          }
        }}
        disabled={formik.isSubmitting}
        className={`py-2 px-4 text-white font-semibold rounded shadow mt-4 ${
          formik.isSubmitting === true ? "bg-blue-200" : "bg-blue-500"
        }`}
      >
        {formik.isSubmitting ? "لطفا چند لحظه صبر کنید" : "ثبت اطلاعات"}
      </button>
    </form>
  );
};

export default DynamicFormNewFFQ;
